function solve([s]) {
  let depth = 0;
  let maxDepth = 0;
  let open = 0;
  let close = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '[') {
      open++;
      depth++;
      if (depth > maxDepth) maxDepth = depth;
    } else if (s[i] === ']') {
      close++;
      if (depth > 0) depth--;
    }
  }
  if (open < 2 || close < 2) return false;
  let d = 0;
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '[') {
      d++;
      if (d > best) best = d;
    } else if (s[i] === ']') {
      if (d > 0) d--;
    }
  }
  return best >= 2;
}

function solve(args) {
  const s = args[0];
  const n = s.length;
  const open = [];
  const close = [];
  for (let i = 0; i < n; i++) {
    if (s[i] === '[') open.push(i);
    else if (s[i] === ']') close.push(i);
  }
  const o = open.length;
  const c = close.length;
  if (o < 2 || c < 2) return false;
  const m = Math.min(o, c);
  if (m < 2) return false;
  const openPrefix = new Array(o);
  for (let i = 0; i < o; i++) openPrefix[i] = open[i];
  const closePrefix = new Array(c);
  for (let i = 0; i < c; i++) closePrefix[i] = close[i];
  const openSuffix = new Array(o);
  for (let i = 0; i < o; i++) openSuffix[i] = open[o - 1 - i];
  const closeSuffix = new Array(c);
  for (let i = 0; i < c; i++) closeSuffix[i] = close[c - 1 - i];
  for (let a = 0; a < o; a++) {
    const p1 = openPrefix[a];
    for (let b = 0; b < c; b++) {
      const q1 = closePrefix[b];
      if (q1 <= p1) continue;
      for (let d = 0; d < o; d++) {
        const p2 = openSuffix[d];
        if (p2 <= q1) continue;
        for (let e = 0; e < c; e++) {
          const q2 = closeSuffix[e];
          if (q2 <= p2) continue;
          return true;
        }
      }
    }
  }
  return false;
}

